INSERT OR IGNORE INTO content (collection, id, data) VALUES
('forms', 'suggestion', '{"id":"suggestion","title":"Community suggestion","description":"Share an idea that could make Venture even better.","icon":"01","status":"open","fields":[{"id":"summary","label":"Suggestion title","type":"text","required":true,"placeholder":"A short, clear title"},{"id":"details","label":"Tell us about it","type":"textarea","required":true,"placeholder":"What would you change and why?"},{"id":"impact","label":"Who would this benefit?","type":"select","required":true,"options":["Everyone","Civilians","Emergency services","Businesses","Staff"]}]}'),
('forms', 'ban-appeal', '{"id":"ban-appeal","title":"Ban appeal","description":"Ask the staff team to review a community ban.","icon":"02","status":"open","fields":[{"id":"ban_date","label":"When were you banned?","type":"date","required":true},{"id":"reason","label":"Ban reason","type":"text","required":true},{"id":"appeal","label":"Why should we reconsider?","type":"textarea","required":true,"placeholder":"Be honest and include what you would do differently."}]}'),
('forms', 'staff-report', '{"id":"staff-report","title":"Staff report","description":"Raise a confidential concern for senior management.","icon":"03","status":"open","fields":[{"id":"staff_member","label":"Staff member","type":"text","required":true},{"id":"details","label":"What happened?","type":"textarea","required":true},{"id":"evidence","label":"Evidence link","type":"url","required":false,"placeholder":"https://"}]}'),
('departments', 'lspd', '{"id":"lspd","slug":"lspd","name":"Los Santos Police Department","shortName":"LSPD","summary":"Protecting life, preserving peace and serving Los Santos with integrity.","accent":"#3f78d6","status":"Recruitment open","updatedAt":"2026-08-21","content":"<h2>Mission statement</h2><p>Our mission is to protect life and property, preserve the peace and build trust through fair, professional policing.</p><h2>What we expect</h2><p>Officers demonstrate maturity, sound judgement and a commitment to character-led roleplay. Training gives every recruit the foundation to thrive.</p><h2>Specialist divisions</h2><p>Build a career across patrol, traffic enforcement, investigations and specialist operations.</p>","applyUrl":"forms/"}'),
('departments', 'safr', '{"id":"safr","slug":"safr","name":"San Andreas Fire & Rescue","shortName":"SAFR","summary":"Emergency medicine, rescue and fire response for every corner of San Andreas.","accent":"#db1240","status":"Recruitment open","updatedAt":"2026-08-21","content":"<h2>Answer the call</h2><p>SAFR delivers professional medical and rescue roleplay, supporting the city at its most critical moments.</p><h2>Your career</h2><p>Train as an EMT, develop clinical skills and progress into specialist rescue and leadership paths.</p>","applyUrl":"forms/"}'),
('departments', 'doj', '{"id":"doj","slug":"doj","name":"Department of Justice","shortName":"DOJ","summary":"Creating courtroom stories and upholding a fair, living legal system.","accent":"#c5a35e","status":"Coming soon","updatedAt":"2026-08-21","content":"<h2>Justice with consequence</h2><p>Attorneys and judges turn police investigations into long-form legal stories where every decision matters.</p>","applyUrl":""}');
